import { DefaultShaper, GlyphInfo } from "./DefaultShaper.js";
//#region src/opentype/shapers/HangulShaper.js
/**
* This is a shaper for the Hangul script, used by the Korean language.
* It does the following:
*   - decompose if unsupported by the font:
*     <LV>   -> <L,V>
*     <LVT>  -> <L,V,T>
*     <LV,T> -> <L,V,T>
*
*   - compose if supported by the font:
*     <L,V>   -> <LV>
*     <L,V,T> -> <LVT>
*     <LV,T>  -> <LVT>
*
*   - reorder tone marks (S is any valid syllable):
*     <S, M> -> <M, S>
*
*   - apply ljmo, vjmo, and tjmo OpenType features to decomposed Jamo sequences.
*
* This logic is based on the following documents:
*   - http://www.microsoft.com/typography/OpenTypeDev/hangul/intro.htm
*   - http://ktug.org/~nomos/harfbuzz-hangul/hangulshaper.pdf
*/
var HangulShaper = class extends DefaultShaper {
	static scripts = ["hang"];
	static zeroMarkWidths = "NONE";
	static planFeatures(plan) {
		plan.add([
			"ljmo",
			"vjmo",
			"tjmo"
		], false);
	}
	static assignFeatures(plan, glyphs) {
		let state = 0;
		let i = 0;
		while (i < glyphs.length) {
			let action;
			let code = glyphs[i].codePoints[0];
			let type = getType(code);
			[action, state] = STATE_TABLE[state][type];
			switch (action) {
				case DECOMPOSE:
					if (!plan.font.hasGlyphForCodePoint(code)) i = decompose(glyphs, i, plan.font);
					break;
				case COMPOSE:
					i = compose(glyphs, i, plan.font);
					break;
				case TONE_MARK:
					reorderToneMark(glyphs, i, plan.font);
					break;
				case INVALID: i = insertDottedCircle(glyphs, i, plan.font);
			}
			i++;
		}
	}
};
const HANGUL_BASE = 44032;
const HANGUL_END = 55204;
const HANGUL_COUNT = 11173;
const L_BASE = 4352;
const V_BASE = 4449;
const T_BASE = 4519;
const V_COUNT = 21;
const T_COUNT = 28;
const L_END = 4370;
const V_END = 4469;
const T_END = 4546;
const DOTTED_CIRCLE = 9676;
const isL = (code) => 4352 <= code && code <= 4447 || 43360 <= code && code <= 43388;
const isV = (code) => 4448 <= code && code <= 4519 || 55216 <= code && code <= 55238;
const isT = (code) => 4520 <= code && code <= 4607 || 55243 <= code && code <= 55291;
const isTone = (code) => 12334 <= code && code <= 12335;
const isLVT = (code) => HANGUL_BASE <= code && code <= HANGUL_END;
const isLV = (code) => code - HANGUL_BASE < HANGUL_COUNT && (code - HANGUL_BASE) % T_COUNT === 0;
const isCombiningL = (code) => L_BASE <= code && code <= L_END;
const isCombiningV = (code) => V_BASE <= code && code <= V_END;
const isCombiningT = (code) => 1 <= code && code <= T_END;
const X = 0;
const L = 1;
const V = 2;
const T = 3;
const LV = 4;
const LVT = 5;
const M = 6;
function getType(code) {
	if (isL(code)) return L;
	if (isV(code)) return V;
	if (isT(code)) return T;
	if (isLV(code)) return LV;
	if (isLVT(code)) return LVT;
	if (isTone(code)) return M;
	return X;
}
const NO_ACTION = 0;
const DECOMPOSE = 1;
const COMPOSE = 2;
const TONE_MARK = 4;
const INVALID = 5;
const STATE_TABLE = [
	[
		[NO_ACTION, 0],
		[NO_ACTION, 1],
		[NO_ACTION, 0],
		[NO_ACTION, 0],
		[DECOMPOSE, 2],
		[DECOMPOSE, 3],
		[INVALID, 0]
	],
	[
		[NO_ACTION, 0],
		[NO_ACTION, 1],
		[COMPOSE, 2],
		[NO_ACTION, 0],
		[DECOMPOSE, 2],
		[DECOMPOSE, 3],
		[INVALID, 0]
	],
	[
		[NO_ACTION, 0],
		[NO_ACTION, 1],
		[NO_ACTION, 0],
		[COMPOSE, 3],
		[DECOMPOSE, 2],
		[DECOMPOSE, 3],
		[TONE_MARK, 0]
	],
	[
		[NO_ACTION, 0],
		[NO_ACTION, 1],
		[NO_ACTION, 0],
		[NO_ACTION, 0],
		[DECOMPOSE, 2],
		[DECOMPOSE, 3],
		[TONE_MARK, 0]
	]
];
function getGlyph(font, code, features) {
	return new GlyphInfo(font, font.glyphForCodePoint(code).id, [code], features);
}
function decompose(glyphs, i, font) {
	let glyph = glyphs[i];
	let s = glyph.codePoints[0] - HANGUL_BASE;
	let t = T_BASE + s % T_COUNT;
	s = s / T_COUNT | 0;
	let l = L_BASE + s / V_COUNT | 0;
	let v = V_BASE + s % V_COUNT;
	if (!font.hasGlyphForCodePoint(l) || !font.hasGlyphForCodePoint(v) || t !== T_BASE && !font.hasGlyphForCodePoint(t)) return i;
	let ljmo = getGlyph(font, l, glyph.features);
	ljmo.features.ljmo = true;
	let vjmo = getGlyph(font, v, glyph.features);
	vjmo.features.vjmo = true;
	let insert = [ljmo, vjmo];
	if (t > T_BASE) {
		let tjmo = getGlyph(font, t, glyph.features);
		tjmo.features.tjmo = true;
		insert.push(tjmo);
	}
	glyphs.splice(i, 1, ...insert);
	return i + insert.length - 1;
}
function compose(glyphs, i, font) {
	let glyph = glyphs[i];
	let code = glyphs[i].codePoints[0];
	let type = getType(code);
	let prev = glyphs[i - 1].codePoints[0];
	let prevType = getType(prev);
	let lv, ljmo, vjmo, tjmo;
	if (prevType === LV && type === T) {
		lv = prev;
		tjmo = glyph;
	} else {
		if (type === V) {
			ljmo = glyphs[i - 1];
			vjmo = glyph;
		} else {
			ljmo = glyphs[i - 2];
			vjmo = glyphs[i - 1];
			tjmo = glyph;
		}
		let l = ljmo.codePoints[0];
		let v = vjmo.codePoints[0];
		if (isCombiningL(l) && isCombiningV(v)) lv = HANGUL_BASE + ((l - L_BASE) * V_COUNT + (v - V_BASE)) * T_COUNT;
	}
	let t = tjmo && tjmo.codePoints[0] || T_BASE;
	if (lv != null && (t === T_BASE || isCombiningT(t))) {
		let s = lv + (t - T_BASE);
		if (font.hasGlyphForCodePoint(s)) {
			let del = prevType === V ? 3 : 2;
			glyphs.splice(i - del + 1, del, getGlyph(font, s, glyph.features));
			return i - del + 1;
		}
	}
	if (ljmo) ljmo.features.ljmo = true;
	if (vjmo) vjmo.features.vjmo = true;
	if (tjmo) tjmo.features.tjmo = true;
	if (prevType === LV) {
		decompose(glyphs, i - 1, font);
		return i + 1;
	}
	return i;
}
function getLength(code) {
	switch (getType(code)) {
		case LV:
		case LVT: return 1;
		case V: return 2;
		case T: return 3;
	}
}
function reorderToneMark(glyphs, i, font) {
	let glyph = glyphs[i];
	let code = glyphs[i].codePoints[0];
	if (font.glyphForCodePoint(code).advanceWidth === 0) return;
	let prev = glyphs[i - 1].codePoints[0];
	let len = getLength(prev);
	glyphs.splice(i, 1);
	return glyphs.splice(i - len, 0, glyph);
}
function insertDottedCircle(glyphs, i, font) {
	let glyph = glyphs[i];
	let code = glyphs[i].codePoints[0];
	if (font.hasGlyphForCodePoint(DOTTED_CIRCLE)) {
		let dottedCircle = getGlyph(font, DOTTED_CIRCLE, glyph.features);
		let idx = font.glyphForCodePoint(code).advanceWidth === 0 ? i : i + 1;
		glyphs.splice(idx, 0, dottedCircle);
		i++;
	}
	return i;
}
//#endregion
export { HangulShaper };
