	range(4096, 4099, CATEGORIES.C);
	set(4100, CATEGORIES.Ra);
	range(4101, 4115, CATEGORIES.C);
	range(4116, 4122, CATEGORIES.C);
	set(4123, CATEGORIES.Ra);
	range(4124, 4128, CATEGORIES.C);
	range(4129, 4138, CATEGORIES.IV);
	range(4139, 4140, CATEGORIES.VPst);
	range(4141, 4142, CATEGORIES.VAbv);
	range(4143, 4144, CATEGORIES.VBlw);
	set(4145, CATEGORIES.VPre);
	set(4146, CATEGORIES.A);
	range(4147, 4149, CATEGORIES.VAbv);
	set(4150, CATEGORIES.A);
	set(4151, CATEGORIES.DB);
	set(4152, CATEGORIES.SM);
	set(4153, CATEGORIES.H);
	set(4154, CATEGORIES.As);
	set(4155, CATEGORIES.MY);
	set(4156, CATEGORIES.MR);
	set(4157, CATEGORIES.MW);
	set(4158, CATEGORIES.MH);
	set(4159, CATEGORIES.C);
	range(4160, 4169, CATEGORIES.GB);
	range(4170, 4171, CATEGORIES.GB);
	set(4174, CATEGORIES.C);
	range(4176, 4177, CATEGORIES.C);
	range(4178, 4181, CATEGORIES.IV);
	range(4182, 4183, CATEGORIES.VPst);
	range(4184, 4185, CATEGORIES.VBlw);
	set(4186, CATEGORIES.Ra);
	range(4187, 4189, CATEGORIES.C);
	range(4190, 4191, CATEGORIES.MY);
	set(4192, CATEGORIES.ML);
	set(4193, CATEGORIES.C);
	set(4194, CATEGORIES.VPst);
	range(4195, 4196, CATEGORIES.PT);
	range(4197, 4198, CATEGORIES.C);
	range(4199, 4200, CATEGORIES.VPst);
	range(4201, 4205, CATEGORIES.PT);
	range(4206, 4208, CATEGORIES.C);
	range(4209, 4212, CATEGORIES.VAbv);
	range(4213, 4225, CATEGORIES.C);
	set(4226, CATEGORIES.MW);
	set(4227, CATEGORIES.VPst);
	set(4228, CATEGORIES.VPre);
	range(4229, 4230, CATEGORIES.VAbv);
	range(4231, 4237, CATEGORIES.SM);
	set(4238, CATEGORIES.C);
	set(4239, CATEGORIES.SM);
	range(4240, 4249, CATEGORIES.GB);
	range(4250, 4252, CATEGORIES.SM);
	set(4253, CATEGORIES.VAbv);
	range(43488, 43492, CATEGORIES.C);
	set(43493, CATEGORIES.VAbv);
	range(43495, 43503, CATEGORIES.C);
	range(43504, 43513, CATEGORIES.GB);
	range(43514, 43518, CATEGORIES.C);
	range(43616, 43631, CATEGORIES.C);
	range(43633, 43635, CATEGORIES.C);
	range(43636, 43638, CATEGORIES.GB);
	set(43642, CATEGORIES.C);
	set(43643, CATEGORIES.PT);
	range(43644, 43645, CATEGORIES.SM);
	range(43646, 43647, CATEGORIES.C);
	set(160, CATEGORIES.GB);
	set(215, CATEGORIES.GB);
	range(8210, 8213, CATEGORIES.GB);
	set(8226, CATEGORIES.GB);
	set(9676, CATEGORIES.DOTTEDCIRCLE);
	range(9723, 9726, CATEGORIES.GB);
	set(8204, CATEGORIES.ZWNJ);
	set(8205, CATEGORIES.ZWJ);
