import { registerShaper } from "./shapers/DefaultShaper.js";
import { DecodeStream } from "restructure";
//#region src/core.js
let logErrors = false;
let formats = [];
function registerFormat(format) {
	formats.push(format);
}
function create(buffer, postscriptName) {
	for (let i = 0; i < formats.length; i++) {
		let format = formats[i];
		if (format.probe(buffer)) {
			let font = new format(new DecodeStream(buffer));
			if (postscriptName) return font.getFont(postscriptName);
			return font;
		}
	}
	throw new Error("Unknown font format");
}
let defaultLanguage = "en";
function setDefaultLanguage(lang = "en") {
	defaultLanguage = lang;
}
//#endregion
export { create, defaultLanguage, logErrors, registerFormat, registerShaper, setDefaultLanguage };
